  /**
   * Its date, as the themes view dates it: the earliest date a name in its folder gives, else the earliest believed time of a file in it; null where nothing dates it (unknown, never a guess). Given whether or not themes are computed.
   */
  date: string | null;
  /**
   * Files found by the engine in what was read (not every file that exists) derived from its raw acquisitions, wherever they lie.
   */
  derived_files: number;
  /**
   * Files found by the engine in what was read (not every file that exists) in its folder.
   */
  files: number;
  /**
   * The experiment's folder, relative to its root.
   */
  folder: string;
  /**
   * Whether the analysis files or results tables found in it count as an analysis of its own, under the completeness settings in force.
   */
  has_analysis: boolean;
  /**
   * The experiment folder's item.
   */
  id: string;
  /**
   * The folder's own name, as written.
   */
  name?: string;
  /**
   * The folder's name read into parts by the tokenizer; empty where not read.
   */
  name_parts?: Array<NamePartItem>;
  /**
   * Whether the run recorded a layout for the name; false: no parts are given.
   */
  name_read?: boolean;
  /**
   * Whose experiment it is: the first folder level below its root, until a setting naming a person replaces it; null for a root's own folder.
   */
  person: string | null;
  /**
   * Raw acquisition files found by the engine in what was read (not every file that exists) in its folder.
   */
  raw_acquisitions: number;
  /**
   * Raw acquisitions found by the engine in what was read (not every file that exists) that are followed by an analysis file found.
   */
  raw_followed: number;
  /**
   * Results tables found by the engine in what was read (not every file that exists) in its folder.
   */
  result_tables: number;
  root_id: string;
  /**
   * One sentence a page shows for it, in plain words.
   */
