  /**
   * The name a row shows: the folder's name with the dates the tokenizer read in it left out; the name itself where the run recorded no layout to read.
   */
  shown_name?: string;
  /**
   * Its theme, where themes are computed; null where none is given.
   */
  theme: string | null;
  /**
   * The words of its theme (its label), beside the theme's number, for a page to show; null where it has no theme or themes are not computed.
   */
