  /**
   * The workflow's identifier.
   */
  id: string;
  /**
   * Whether the run applies it.
   */
  in_force: boolean;
  /**
   * Its name.
   */
  name: string;
  /**
   * Suggested by the engine, or declared by a person.
   */
